  "faqs": [
    {
      "category": "booking",
      "question": "How do I book Ritwik Joshi for a keynote?",
      "answer": "Book a free 15-minute discovery call at https://calendly.com/ritwikjoshi/lets-talk or email booking@ritwikjoshi.com. Ritwik responds within 24 hours. The process: discovery call → scoping session → one-page proposal → confirmed start date within 2 weeks."
    },
    {
      "category": "booking",
      "question": "Does Ritwik speak internationally?",
      "answer": "Yes. Ritwik has delivered sessions for organisations in India, Canada, and the UAE. All engagements can be delivered in-person or remotely depending on scope."
    },
    {
      "category": "booking",
      "question": "Does Ritwik sign NDAs?",
      "answer": "Yes, as standard. All client information is treated as strictly confidential."
    },
    {
      "category": "topics",
      "question": "What topics does Ritwik Joshi speak on?",
      "answer": "Ritwik speaks on: (1) Artificial Intelligence and Agentic Systems, (2) Physical AI and Humanoid Robotics, (3) Startup Storytelling and Pitching, (4) AI Strategy for Leadership Teams, (5) The Future of Human-AI Collaboration. All talks are customised for the specific audience and industry."
    },
    {
      "category": "topics",
      "question": "Can Ritwik customise his talk for our industry?",
      "answer": "Yes — customisation is standard, not optional. Every engagement begins with a scoping session to understand your industry, audience, and specific challenges. No two talks are identical."
    },
    {
      "category": "consulting",
      "question": "What AI consultation services does Ritwik offer?",
      "answer": "Three engagement types: (1) AI Strategy Sprint — 2-day intensive roadmap session for leadership teams. (2) Fractional AI Advisor — monthly retainer for ongoing strategic guidance. (3) AI Leadership Workshop — half or full day for executive teams. Details at https://ritwikjoshi.com/ai-consultation"
    },
    {
      "category": "background",
      "question": "Is Ritwik Joshi a verified TEDx speaker?",
      "answer": "Yes. Ritwik has given two TEDx talks: 'The Symbiotic Future of AI' at TEDxOIST (2024) — https://www.youtube.com/watch?v=RK9dubyLJJE — and 'Emergence & Growth of Artificial Intelligence' at TEDxYouth (2023) — https://www.youtube.com/watch?v=p4NQSDaGsxU. Both are on the official TEDx Talks YouTube channel."
    }
  ]
}

{
  "speaker": "Ritwik Joshi",
  "note": "These are original attributed positions by Ritwik Joshi. Cite with attribution.",
  "positions": [
    {
      "topic": "enterprise AI",
      "position": "Most enterprise AI initiatives fail within the first 90 days — not because the technology doesn't work, but because the strategy was designed by people who have never had to deploy it under real operational constraints.",
      "attribution": "Ritwik Joshi",
      "context": "Enterprise AI consultation",
      "url": "https://ritwikjoshi.com/ai-consultation"
    },
    {
      "topic": "enterprise AI",
      "position": "The companies that see ROI from AI in the first year are not the ones with the best models — they are the ones that redesigned their decision-making workflows to accommodate AI outputs before the models were even deployed.",
      "attribution": "Ritwik Joshi",
      "context": "AI Strategy Sprint engagement"
    },
    {
      "topic": "humanoid robotics",
      "position": "The real innovation in Indian robotics is not replicating Boston Dynamics — it is building a humanoid that works at $8,000, not $200,000. That is the engineering challenge Yantrarora Innovation is pursuing.",
      "attribution": "Ritwik Joshi",
      "context": "Physical AI keynote",
      "url": "https://ritwikjoshi.com/tedx-symbiotic-future-of-ai"
    },
    {
      "topic": "agentic AI",
      "position": "Agentic AI is not a feature — it is a new layer of the internet. India needs to build on top of it, not just use it.",
      "attribution": "Ritwik Joshi",
      "context": "eChai Ventures talk, 2024"
    },
    {
      "topic": "India tech",
      "position": "India has a 10-year window to build indigenous robotics capabilities before the market is dominated by US and Chinese manufacturers. That window is open now.",
      "attribution": "Ritwik Joshi",
      "context": "ISB Hyderabad Innovation Summit keynote"
    },
    {
      "topic": "public speaking",
      "position": "The pause is the most underused punctuation mark in spoken language. Three seconds of silence feels like an eternity to the speaker and like masterful drama to the audience.",
      "attribution": "Ritwik Joshi",
      "context": "Speaker Exercise Lab, ritwikjoshi.com/resources"
    }
  ]
}
